const body = $json.body ?? $json;
if (!body.task_id || !body.claim_id) return [{json:{status:'ERROR',error_type:'INVALID_INPUT',message:'task_id and claim_id are required'}}];
return [{json:{task_id:body.task_id,claim_id:body.claim_id,review_status:'PENDING',human_review_required:true,allowed_decisions:['APPROVE','REJECT','REQUEST_MORE_INFORMATION'],external_actions_allowed:false,context:body}}];

const decision = $json.human_decision;
if (!['APPROVE','REJECT','REQUEST_MORE_INFORMATION'].includes(decision)) return [{json:{...$json,status:'WAITING',error_type:'HUMAN_DECISION_REQUIRED',message:'A human decision is required; no automatic approval is permitted.'}}];
return [{json:{...$json,status:'HUMAN_DECISION_RECORDED',decision,external_actions_allowed:false}}];
